// Load 30-day calendar and select today's Reel
const calendar = require('./reels-calendar-30day.json');

const now = new Date();
const today = now.toISOString().split('T')[0];

const todayEntry = calendar.days.find(d => d.date === today);

if (!todayEntry) {
  return [{ json: { error: 'No Reel scheduled for today', date: today } }];
}

const post = todayEntry.post;

return [{
  json: {
    day: todayEntry.day,
    date: todayEntry.date,
    theme: todayEntry.theme,
    title: todayEntry.title,
    hook: post.hook,
    imageFile: post.image_file,
    imageUrl: `https://pawcasso-atelier.vercel.app/gallery/${post.image_file}`,
    videoStyle: post.video_style,
    duration: post.duration,
    caption: post.caption,
    hashtags: post.hashtags.join(' '),
    trendingAudio: post.trending_audio,
    cta: post.cta,
    engagementPrompt: post.engagement_prompt,
    postTime: `${todayEntry.date}T11:00:00-07:00`,
    fullCaption: `${post.caption}\n\n${post.engagement_prompt}\n\n.\n.\n.\n\n${post.hashtags.join(' ')}`
  }
}];

