// Push review page HTML to GitHub for mobile access
const reel = $input.all()[0].json;
const filename = `reel-day${String(reel.day).padStart(2, '0')}.html`;
const content = Buffer.from(reel.reviewPageHtml).toString('base64');

return [{
  json: {
    filename,
    content,
    message: `Add Reel review page for Day ${reel.day}: ${reel.title}`,
    path: `website/public/reels-review/${filename}`
  }
}];
